import {projectPickerOptions,selectableProjects as projects} from './project-directory.mjs';
import {download as exportFile} from './ui.mjs';
import {withStableView} from './view-stability.mjs';
import {list as scopedDraftList,write as scopedDraftWrite,keys as scopedDraftKeys,hasDraftScope} from './state.mjs';
import {documentExportButtons,bindDocumentExports} from './document-export.mjs';
import {writingDetailHeading,catalog,guideMarkup,bindGuide,decorateWritingDetail} from './writing-catalog.mjs';
import {} from './state.mjs';
import {registerEditor,markEditorSaved} from './edit-guard.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const supportFields={
 proposal:[['background','研究背景与意义'],['question','研究问题与目标'],['content','研究内容与技术路线'],['method','研究方法与资料来源'],['schedule','计划安排与预期成果']],
 summary:[['topic','综述主题与范围'],['sources','已阅读文献与来源'],['dimensions','比较维度'],['findings','主要发现与争议'],['gap','研究空白与问题']],
 taskbook:[['goals','研究目标'],['content','研究内容与任务'],['method','研究方法与资料来源'],['schedule','计划安排'],['deliverable','预期成果']],
 practice:[['unit','实践单位'],['position','岗位'],['start','开始日期','date'],['end','结束日期','date'],['experience','实际工作内容与经历'],['reflection','收获与反思']],
 idea:[['major','专业'],['interest','研究兴趣'],['question','核心研究问题'],['data','可获得的数据与材料'],['method','拟采用的方法'],['deliverable','预期成果']],
 questionnaire:[['goal','研究目标'],['population','目标人群'],['dimensions','调查维度'],['instructions','答题说明'],['questions','问题与选项（每行记录一个问题，可在右侧编辑）']],
 analysis:[['question','研究问题'],['source','真实数据来源'],['variables','变量与类型'],['quality','样本、缺失值与清理说明'],['method','预期分析方法'],['existing','已有计算结果（可选，注明计算工具）']]
};
const boundaries={proposal:'本地开题框架 · 请根据导师要求与真实资料核对研究问题、方法和计划。',summary:'本地综述框架 · 请核对每条文献的来源、观点与研究空白。',questionnaire:'本地问卷草稿 · 在线发布、二维码、答卷回收与信效度计算尚未接入。',analysis:'本地分析计划 · 当前不执行统计运算，不输出虚构 p 值、回归系数或分析结论。',practice:'本地报告框架 · 请填写真实实践经历，当前未调用 AI。',idea:'本地课题思路框架 · 不自动检索文献或评估创新性。',taskbook:'本地任务书框架 · 根据学校与导师要求人工核对，当前未调用 AI。'};
export function supportText(kind,v){const title=v.title||'未命名任务';const name=catalog.find(t=>t[0]===kind)?.[1]||kind;return [title,name+' · 本地整理',...supportFields[kind].flatMap(([key,label])=>['',label,v[key]?.trim()||'（待填写真实内容）']),'',boundaries[kind]].join('\n');}
export function mountWritingSupport(...args){return withStableView(document.querySelector('.dashboard'),()=>mountWritingSupportContents(...args));}function mountWritingSupportContents(kind,draftId,projectId,ctx){if(!supportFields[kind])return false;let drafts=[];try{drafts=scopedDraftList(scopedDraftKeys.drafts);}catch{}if(!Array.isArray(drafts))drafts=[];const loaded=drafts.find(d=>String(d.id)===String(draftId));let savedId=loaded?.id;const name=catalog.find(t=>t[0]===kind)[1],fields=loaded?.supportFields||{},main=document.querySelector('.dashboard');main.classList.add('creation-page');main.classList.remove('category-view');main.innerHTML=`${writingDetailHeading(kind)}${guideMarkup(kind==='idea'?'topic':kind)}<div class="support-boundary" role="note">${boundaries[kind]}</div><div class="creation-grid"><section class="card creation-input"><h2>任务信息</h2><form id="support-form"><label for="support-project">所属项目（可选）</label><select id="support-project" data-project-picker data-project-ref="${esc(loaded?.projectId||projectId||'')}">${projectPickerOptions(loaded?.projectId||projectId||'')}</select><label for="support-title">题目 / 主题 *</label><input id="support-title" required minlength="2" maxlength="200" value="${esc(fields.title??loaded?.title??'')}">${supportFields[kind].map(([key,label,type])=>`<label for="support-${key}">${label}</label>${type?`<input id="support-${key}" type="${type}" value="${esc(fields[key]||'')}">`:`<textarea id="support-${key}" rows="3" maxlength="5000">${esc(fields[key]||'')}</textarea>`}`).join('')}<p id="support-error" role="alert"></p><button class="btn primary" type="submit">整理本地框架 →</button></form></section><section class="card creation-output"><h2>草稿与编辑</h2><p>以下仅整理你输入的内容；未填写的信息保持待填写。</p><label for="support-output">编辑任务内容</label><textarea id="support-output" rows="23" maxlength="100000">${esc(loaded?.text||'')}</textarea><div class="creation-actions"><button id="support-save" class="btn secondary">保存草稿</button><button id="support-export" class="btn primary">导出 TXT</button></div>${documentExportButtons('support')}<p id="support-status" role="status"></p></section></div>`;
decorateWritingDetail(main,kind);
bindGuide();
const guideToggle=main.querySelector('.guide-toggle'),toggleGuide=guideToggle?.onclick;if(toggleGuide)guideToggle.onclick=event=>withStableView(main,()=>toggleGuide.call(guideToggle,event));
const $=s=>document.querySelector(s);const values=()=>({title:$('#support-title').value,...Object.fromEntries(supportFields[kind].map(([key])=>[key,$('#support-'+key).value]))});
$('#support-form').onsubmit=e=>withStableView(main,()=>{e.preventDefault();const v=values();if(kind==='practice'&&v.start&&v.end&&v.end<v.start){$('#support-error').textContent='结束日期不能早于开始日期。';return;}$('#support-error').textContent='';if($('#support-output').value.trim()){ctx.modal('保留当前草稿',`<p>整理框架会替换右侧内容。请先保存或导出；确认后再替换。</p><button class="btn primary" id="support-replace">确认替换框架</button>`);$('#support-replace').onclick=()=>withStableView(main,()=>{$('#support-output').value=supportText(kind,v);document.querySelector('#workspace-dialog')?.close();});return;}$('#support-output').value=supportText(kind,v);$('#support-status').textContent='框架已整理，请根据实际材料编辑。';});
const saveDraft=()=>{try{const rows=scopedDraftList(scopedDraftKeys.drafts);if(!Array.isArray(rows))throw Error();const v=values(),now=new Date().toISOString(),text=$('#support-output').value,previous=rows.find(d=>d.id===savedId)||loaded;const item={...previous,id:savedId||crypto.randomUUID(),title:v.title.trim()||'未命名'+name,tool:kind,projectId:$('#support-project').value,supportFields:v,text,html:text.split('\n').map(l=>`<p>${esc(l)}</p>`).join(''),createdAt:previous?.createdAt||now,updatedAt:now,stage:'draft'};const i=rows.findIndex(d=>d.id===item.id);if(i<0)rows.unshift(item);else rows[i]=item;scopedDraftWrite(scopedDraftKeys.drafts,rows);savedId=item.id;markEditorSaved();$('#support-status').textContent=hasDraftScope()?'编辑内容已暂存，尚未保存到账户。':'草稿已自动保存到当前浏览器。';return true;}catch{$('#support-status').textContent='草稿保存失败，当前内容仍保留，请导出备份。';return false;}};
$('#support-save').onclick=()=>{if(!$('#support-form').reportValidity())return false;const v=values();if(v.title.trim().length<2){$('#support-error').textContent='请填写至少 2 个字的题目或主题。';return false;}if(kind==='practice'&&v.start&&v.end&&v.end<v.start){$('#support-error').textContent='结束日期不能早于开始日期。';return false;}return withStableView(main,saveDraft);};
$('#support-export').onclick=async()=>{const exportStatus=$('#support-status');const text=$('#support-output').value;if(!text.trim()){exportStatus.textContent='请先整理框架或填写内容。';return;}try{const exported=await exportFile((values().title||name)+'.txt',text);exportStatus.textContent=exported.message;}catch(error){exportStatus.textContent=error.message;}};
bindDocumentExports('support',()=>$('#support-output').value,()=>values().title,$('#support-status'));if(ctx)registerEditor({label:name+'草稿',ctx,getValue:()=>({...values(),projectId:$('#support-project').value,text:$('#support-output').value}),save:saveDraft,...(!hasDraftScope()?{saveDraft}:{})});return true;}
